import 'likerts.dart';
import 'visibility.dart';
class SurveyProgress{final int current,total,visited;const SurveyProgress(this.current,this.total,this.visited);@override bool operator==(Object other)=>other is SurveyProgress&&current==other.current&&total==other.total&&visited==other.visited;@override int get hashCode=>Object.hash(current,total,visited);}
List<SurveyPage> _pages(Collection collection)=>collection.pages??[SurveyPage.fromJson({'id':'survey','questionIds':collection.questions.map((q)=>q.id).toList()})];
List<int> pageRoute(Collection collection,Map<String,dynamic> answers){final all=_pages(collection),ids={for(var i=0;i<all.length;i++)all[i].id:i},visible=visibleAnswers(collection.questions,answers),available=<String>{},route=<int>[];var current=0;while(current<all.length){route.add(current);available.addAll(all[current].questionIds);PageBranch? branch;for(final candidate in all[current].branches){if(conditionMatches(candidate.when,available.contains(candidate.when.questionId)?visible[candidate.when.questionId]:null)){branch=candidate;break;}}current=branch==null?current+1:ids[branch.goToPageId]??all.length;}return route;}
Map<String,dynamic> routedAnswers(Collection collection,Map<String,dynamic> answers){var result=visibleAnswers(collection.questions,answers);final all=_pages(collection);for(var pass=0;pass<=collection.questions.length;pass++){final reached=pageRoute(collection,result).expand((i)=>all[i].questionIds).toSet();final filtered=visibleAnswers(collection.questions,Map.fromEntries(result.entries.where((entry)=>reached.contains(entry.key))));if(filtered.length==result.length)return filtered;result=filtered;}throw const FormatException('Survey route did not stabilize');}
class SurveyFlow{final Collection collection;late Map<String,dynamic> _answers;late List<int> _route;late List<int> _history;late int _current;SurveyFlow(this.collection,[Map<String,dynamic> answers=const{}]){_answers=routedAnswers(collection,{...answers});_route=pageRoute(collection,_answers);_current=_route.firstOrNull??0;_history=[_current];}SurveyPage get page=>_pages(collection)[_current];Map<String,dynamic> get answers=>Map.unmodifiable(_answers);SurveyProgress get progress=>SurveyProgress(_current+1,_pages(collection).length,_history.length);void setAnswer(String id,dynamic value){final old=[..._history];if(value==null){_answers.remove(id);}else{_answers[id]=value;}_answers=routedAnswers(collection,_answers);_route=pageRoute(collection,_answers);if(!_route.contains(_current)){var shared=_route.firstOrNull??0;for(var i=0;i<old.length&&i<_route.length&&old[i]==_route[i];i++)shared=_route[i];_current=shared;}_history=_route.take(_route.indexOf(_current)+1).toList();}bool next(){final index=_route.indexOf(_current);if(index<0||index+1>=_route.length)return false;_current=_route[index+1];_history=_route.take(index+2).toList();return true;}bool back(){if(_history.length<2)return false;_history.removeLast();_current=_history.last;return true;}}
